using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Diagnostics;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using CircuitoStudio;
class CrashRecoveryTests {
 static int n;static BindingFlags instance=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool b,string message){n++;if(!b)throw new Exception(message);}
 static object Get(object target,string field){return target.GetType().GetField(field,instance).GetValue(target);}
 static void Set(object target,string field,object value){target.GetType().GetField(field,instance).SetValue(target,value);}
 static object Call(object target,string method,params object[] args){return target.GetType().GetMethod(method,instance).Invoke(target,args);}
 static Type StudioType {get{return typeof(Project).Assembly.GetType("CircuitoStudio.Studio");}}
 static void Isolate(string directory){StudioType.GetField("userData",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,Path.Combine(directory,"profile"));}
 static Project Fixture(){var p=Project.CreateSample();p.Name="Recuperação ensaio Ω";p.Client="Cliente ç";p.Site="Instalação 北";p.Designer="Responsável";p.DescriptionLine1="Linha um";p.DescriptionLine3="Linha três";p.Notes="Dados de ensaio";p.DrawingTheme=DiagramTheme.Monocromatico;p.StandardReference="Referência de ensaio";p.CalculationMethod="Método de ensaio";var b=p.Boards[0];b.Enclosure.Manufacturer="Invólucro de ensaio";b.Enclosure.Reference="REF-E";var c=b.Circuits[0];c.DiagramLabel="Etiqueta recuperada";c.DrawingSymbol=DiagramSymbol.Inversor;c.DiagramX=450;c.DiagramY=500;c.DinModules=4;c.DinRow=2;c.DinColumn=3;c.PhaseLocked=true;c.Cable.AmpacityA=60;c.Cable.Reference="Cabo de ensaio";c.Protection.BreakingCapacityKA=10;c.DriveMotor=new DriveMotorData{DriveReference="Drive ensaio",InputRatedA=16,OutputRatedA=20,OutputVoltageV=380,MotorReference="Motor ensaio",MotorRatedA=18,MotorVoltageV=380,MotorShaftKw=5.5,Source="Amostra sintética"};c.PowerFactor=.9;c.ReactiveKvarOverride=.9;p.Source.ShortCircuitKA=12.5;p.Source.CurrentBasis=SourceCurrentBasis.RedeMT;p.Source.UpstreamVoltageV=20000;p.Source.NetworkReference="Dados MT de ensaio Ω";p.Source.TransformerKva=100;p.Source.TransformerCopperLossKw=2;var second=new Board{Id="Q2",Name="Quadro intermediário",Voltage=380};var third=new Board{Id="Q3",Name="Quadro final",Voltage=380};b.Circuits.Add(new Circuit{Id="C3",Name="Alimentador 1",ChildBoardId="Q2",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=380,PowerKw=999,CableMm2=25});second.Circuits.Add(new Circuit{Id="C4",Name="Carga intermediária",Voltage=220,PowerKw=2});second.Circuits.Add(new Circuit{Id="C5",Name="Alimentador 2",ChildBoardId="Q3",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=380,PowerKw=888,CableMm2=16});third.Circuits.Add(new Circuit{Id="C6",Name="Carga final",Voltage=380,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=3});p.Boards.Add(second);p.Boards.Add(third);c.CurveStudy=new CurveStudyData{Upstream=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;10;20\n100;1;2","Montante ensaio"),Downstream=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;1;2\n100;0.1;0.2","Jusante ensaio")};MotorStarting.Apply(p,third,third.Circuits[0],new MotorStartingData{ShaftKw=2.7,Efficiency=.9,StartingCurrentA=30,StartingPowerFactor=.3,StartingSeconds=2,AllowedStartDropPercent=10,Source="Motor da recuperação; ensaio sintético"},PhaseMode.Trifasico,380,.8);p.Validate();return p;}
 static bool Same(object a,object b){if(a==null||b==null)return a==b;if(a.GetType()!=b.GetType())return false;Type type=a.GetType();if(type.IsPrimitive||type.IsEnum||a is string||a is decimal)return a.Equals(b);if(a is IEnumerable){var x=((IEnumerable)a).Cast<object>().ToArray();var y=((IEnumerable)b).Cast<object>().ToArray();return x.Length==y.Length&&x.Zip(y,Same).All(v=>v);}return type.GetProperties(BindingFlags.Instance|BindingFlags.Public).Where(p=>p.CanRead&&p.GetIndexParameters().Length==0).All(p=>Same(p.GetValue(a,null),p.GetValue(b,null)))&&type.GetFields(BindingFlags.Instance|BindingFlags.Public).All(f=>Same(f.GetValue(a),f.GetValue(b)));}
 static void Child(string directory,string marker){Isolate(directory);Application.EnableVisualStyles();using(var studio=(Form)Activator.CreateInstance(StudioType,true)){studio.CreateControl();var p=Fixture();Set(studio,"project",p);Set(studio,"board",p.Boards[0]);Set(studio,"circuit",p.Boards[0].Circuits[0]);Set(studio,"currentFile",Path.Combine(directory,"main.circuito"));Call(studio,"Change");string recovery=(string)Call(studio,"RecoveryFile");var watch=Stopwatch.StartNew();while(!File.Exists(recovery)&&watch.ElapsedMilliseconds<45000){Application.DoEvents();Thread.Sleep(40);}if(!File.Exists(recovery))throw new Exception("Autosave timeout");Project.Load(recovery);File.WriteAllText(marker+".tmp",recovery);File.Move(marker+".tmp",marker);while(true){Application.DoEvents();Thread.Sleep(40);}}}
 [STAThread] static void Main(string[] args){if(args.Length==3&&args[0]=="--child"){Child(args[1],args[2]);return;}string directory=Path.Combine(Path.GetTempPath(),"crash-recovery-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);Process child=null;try{
  var expected=Fixture();string main=Path.Combine(directory,"main.circuito"),marker=Path.Combine(directory,"ready.txt");expected.Name="Backup anterior";expected.Save(main);expected.Name="Recuperação ensaio Ω";expected.Save(main);Check(File.ReadAllText(main).Contains("\"FileVersion\":4")&&File.ReadAllText(main).Contains("motor-start-v1"),"Crash fixture includes guarded motor format");Check(Project.Load(main+".bak").Name=="Backup anterior","Backup baseline");
  child=Process.Start(new ProcessStartInfo(typeof(CrashRecoveryTests).Assembly.Location,"--child \""+directory+"\" \""+marker+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=directory});var watch=Stopwatch.StartNew();while(!File.Exists(marker)&&!child.HasExited&&watch.ElapsedMilliseconds<50000)Thread.Sleep(50);Check(File.Exists(marker),"Child did not produce real 30-second autosave"+(child.HasExited?": "+child.StandardError.ReadToEnd():""));child.Kill();Check(child.WaitForExit(5000)&&child.ExitCode!=0,"Child terminated abruptly without normal close");string recovery=File.ReadAllText(marker);Check(Path.GetFullPath(recovery).StartsWith(directory+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Recovery stays in isolated profile");var recovered=Project.Load(recovery);Check(Same(expected,recovered),"All public project state survives abrupt process termination");
  File.WriteAllText(main,"corrupted main file");bool rejected=false;try{Project.Load(main);}catch{rejected=true;}Check(rejected,"Corrupt main rejected");Check(Project.Load(main+".bak").Name=="Backup anterior","Backup remains restorable after main corruption");
  Isolate(directory);Application.EnableVisualStyles();using(var studio=(Form)Activator.CreateInstance(StudioType,true)){studio.CreateControl();Check((bool)Call(studio,"RestoreRecovery",recovery),"Application restores recovery");Check(Same(expected,(Project)Get(studio,"project")),"Restored application keeps all project state");Check(Get(studio,"currentFile")==null,"Recovery opens as separate unsaved copy");Check(File.ReadAllText(main)=="corrupted main file","Recovery does not overwrite original file");var active=Get(studio,"project");Set(studio,"dirty",false);bool failed=false;try{Call(studio,"RestoreRecovery",main);}catch(TargetInvocationException){failed=true;}Check(failed&&Object.ReferenceEquals(active,Get(studio,"project")),"Invalid recovery does not replace active project");expected.Name="Backup anterior";Check((bool)Call(studio,"RestoreRecovery",main+".bak")&&Same(expected,(Project)Get(studio,"project")),"Application also restores complete backup as copy");Set(studio,"dirty",false);}
  Console.WriteLine("PASS: "+n+" crash recovery assertions; real autosave and abrupt child termination");
 }finally{if(child!=null){if(!child.HasExited){child.Kill();child.WaitForExit(5000);}child.Dispose();}Directory.Delete(directory,true);}}
}
